import { useMemo, useState, useEffect } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'ok' | 'warning' | 'over';

interface Project {
  id: string;
  name: string;
  quotaUsed: number;
  status: ProjectStatus;
}

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' }> = {
  ok: { label: 'В норме', tone: 'success' },
  warning: { label: 'Близко к лимиту', tone: 'warning' },
  over: { label: 'Квота превышена', tone: 'danger' },
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Marketing Site Redesign', quotaUsed: 34, status: 'ok' },
  { id: 'p2', name: 'Internal Analytics Pipeline', quotaUsed: 88, status: 'warning' },
  { id: 'p3', name: 'Mobile App v2', quotaUsed: 61, status: 'ok' },
  { id: 'p4', name: 'Billing Migration', quotaUsed: 104, status: 'over' },
  { id: 'p5', name: 'Support Portal', quotaUsed: 47, status: 'ok' },
  { id: 'p6', name: 'Data Warehouse ETL', quotaUsed: 92, status: 'warning' },
  { id: 'p7', name: 'Customer Onboarding Flow', quotaUsed: 18, status: 'ok' },
  { id: 'p8', name: 'Legacy API Sunset', quotaUsed: 110, status: 'over' },
  { id: 'p9', name: 'Design System Tokens', quotaUsed: 55, status: 'ok' },
  { id: 'p10', name: 'Fraud Detection Model', quotaUsed: 96, status: 'warning' },
  { id: 'p11', name: 'Search Reindexing', quotaUsed: 29, status: 'ok' },
  { id: 'p12', name: 'Notification Service', quotaUsed: 101, status: 'over' },
];

const ALL_STATUSES: ProjectStatus[] = ['ok', 'warning', 'over'];
const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
  };

  const resetFilters = () => setActiveStatuses([]);

  const filteredProjects = useMemo(() => {
    if (activeStatuses.length === 0) return PROJECTS;
    return PROJECTS.filter((p) => activeStatuses.includes(p.status));
  }, [activeStatuses]);

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));

  useEffect(() => {
    setPage(1);
  }, [activeStatuses]);

  const visibleProjects = filteredProjects.slice(
    (page - 1) * PAGE_SIZE,
    page * PAGE_SIZE
  );

  return (
    <div
      className="jx-surface"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 16,
        padding: 20,
        borderRadius: 'var(--jx-radius, 12px)',
        border: '1px solid var(--jx-border)',
        background: 'var(--jx-surface)',
        maxWidth: 560,
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
        {ALL_STATUSES.map((status) => (
          <JxChip
            key={status}
            active={activeStatuses.includes(status)}
            removable={activeStatuses.includes(status)}
            onClick={() => toggleStatus(status)}
            onRemove={() => toggleStatus(status)}
          >
            {STATUS_META[status].label}
          </JxChip>
        ))}
      </div>

      {visibleProjects.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="Под выбранные фильтры не подошёл ни один проект."
          action={
            <JxButton variant="secondary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column' }}>
          {visibleProjects.map((project, idx) => (
            <div
              key={project.id}
              style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                gap: 16,
                padding: '12px 4px',
                borderBottom:
                  idx < visibleProjects.length - 1
                    ? '1px solid var(--jx-rule)'
                    : 'none',
              }}
            >
              <span style={{ color: 'var(--jx-text)', fontWeight: 500 }}>
                {project.name}
              </span>
              <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
                <JxProgressCircle value={project.quotaUsed} max={100} showValue />
                <JxBadge tone={STATUS_META[project.status].tone}>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </div>
            </div>
          ))}
        </div>
      )}

      {visibleProjects.length > 0 && (
        <JxPagination total={pageCount} page={page} onPageChange={setPage} />
      )}
    </div>
  );
}

